const rows = $input.all().map(item => item.json);
const now = Date.now();
const count = (test) => rows.filter(test).length;

// 1. How many reports are in each status
const total = rows.length;
const newCount = count(r => r.status === 'new');
const triaged = count(r => r.status === 'triaged');
const needsReview = count(r => r.status === 'needs_review');

// 2. Share decided by AI alone
const decided = triaged + needsReview;
const autoTriageRate = decided ? Math.round(triaged / decided * 100) : 0;

// 3. How often the AI disagreed with the user's reason
const withAI = rows.filter(r => r.ai_category);
const relabeled = withAI.filter(r => r.ai_category !== r.user_reason).length;
const relabelRate = withAI.length ? Math.round(relabeled / withAI.length * 100) : 0;

// 4. SLA breaches
const slaBreaches = count(r => r.escalated_at);

// 5. Silent-failure checks
const STUCK_MINUTES = 10;
const stuckReports = rows
  .filter(r => r.status === 'new' && (now - new Date(r.received_at).getTime()) / 60000 > STUCK_MINUTES)
  .map(r => r.report_id);
const missingCategory = rows
  .filter(r => r.status !== 'new' && !r.ai_category)
  .map(r => r.report_id);

return [{ json: {
  total, newCount, triaged, needsReview,
  autoTriageRate, relabeled, relabelRate,
  slaBreaches, stuckReports, missingCategory
}}];
